mapper.select:
SELECT * FROM orders


        AND (number LIKE CONCAT('%', #{orderPageQueryDTO.keyword}, '%')
             OR consignee LIKE CONCAT('%', #{orderPageQueryDTO.keyword}, '%'))


        AND status = #{orderPageQueryDTO.status}


        AND order_time >= #{orderPageQueryDTO.beginTime}


        AND order_time <= #{orderPageQueryDTO.endTime}


ORDER BY order_time DESC
